import { decodeSenderKeyDistributionRow, decodeSenderKeyRecord, encodeSenderKeyRecord, toSignalAddressParts } from 'zapo-js/signal';
import { asNumber, asString } from 'zapo-js/util';
import { BaseSqliteStore } from './BaseSqliteStore.js';
export class SenderKeySqliteStore extends BaseSqliteStore {
    constructor(options) {
        super(options, ['senderKey']);
    }
    async upsertSenderKey(record) {
        const db = await this.getConnection();
        const sender = toSignalAddressParts(record.sender);
        db.run(`INSERT INTO sender_keys (
                session_id,
                group_id,
                sender_user,
                sender_server,
                sender_device,
                record
            ) VALUES (?, ?, ?, ?, ?, ?)
            ON CONFLICT(session_id, group_id, sender_user, sender_server, sender_device) DO UPDATE SET
                record=excluded.record`, [
            this.options.sessionId,
            record.groupId,
            sender.user,
            sender.server,
            sender.device,
            encodeSenderKeyRecord(record)
        ]);
    }
    async upsertSenderKeyDistribution(record) {
        const db = await this.getConnection();
        const sender = toSignalAddressParts(record.sender);
        this.upsertSenderKeyDistributionRow(db, record, sender);
    }
    async upsertSenderKeyDistributions(records) {
        if (records.length === 0) {
            return;
        }
        await this.withTransaction((db) => {
            for (const record of records) {
                const sender = toSignalAddressParts(record.sender);
                this.upsertSenderKeyDistributionRow(db, record, sender);
            }
        });
    }
    async getGroupSenderKeyList(groupId) {
        const db = await this.getConnection();
        const senderRows = db.all(`SELECT group_id, sender_user, sender_server, sender_device, record
             FROM sender_keys
             WHERE session_id = ? AND group_id = ?`, [this.options.sessionId, groupId]);
        const distributionRows = db.all(`SELECT group_id, sender_user, sender_server, sender_device, key_id, timestamp_ms
             FROM sender_key_distribution
             WHERE session_id = ? AND group_id = ?`, [this.options.sessionId, groupId]);
        const skList = new Array(senderRows.length);
        for (let index = 0; index < senderRows.length; index += 1) {
            const row = senderRows[index];
            skList[index] = decodeSenderKeyRecord(row.record, asString(row.group_id, 'sender_keys.group_id'), {
                user: asString(row.sender_user, 'sender_keys.sender_user'),
                server: asString(row.sender_server, 'sender_keys.sender_server'),
                device: asNumber(row.sender_device, 'sender_keys.sender_device')
            });
        }
        const skDistribList = new Array(distributionRows.length);
        for (let index = 0; index < distributionRows.length; index += 1) {
            skDistribList[index] = decodeSenderKeyDistributionRow(distributionRows[index]);
        }
        return {
            skList,
            skDistribList
        };
    }
    async getDeviceSenderKey(groupId, sender) {
        const db = await this.getConnection();
        const target = toSignalAddressParts(sender);
        const row = db.get(`SELECT group_id, sender_user, sender_server, sender_device, record
             FROM sender_keys
             WHERE session_id = ?
               AND group_id = ?
               AND sender_user = ?
               AND sender_server = ?
               AND sender_device = ?`, [this.options.sessionId, groupId, target.user, target.server, target.device]);
        if (!row) {
            return null;
        }
        return decodeSenderKeyRecord(row.record, asString(row.group_id, 'sender_keys.group_id'), {
            user: asString(row.sender_user, 'sender_keys.sender_user'),
            server: asString(row.sender_server, 'sender_keys.sender_server'),
            device: asNumber(row.sender_device, 'sender_keys.sender_device')
        });
    }
    async getDeviceSenderKeyDistributions(groupId, senders) {
        if (senders.length === 0) {
            return [];
        }
        const db = await this.getConnection();
        const rows = db.all(`SELECT group_id, sender_user, sender_server, sender_device, key_id, timestamp_ms
             FROM sender_key_distribution
             WHERE session_id = ? AND group_id = ?`, [this.options.sessionId, groupId]);
        const map = new Map();
        for (const row of rows) {
            map.set(this.distributionRowKey(row), decodeSenderKeyDistributionRow(row));
        }
        const records = new Array(senders.length);
        for (let index = 0; index < senders.length; index += 1) {
            const target = toSignalAddressParts(senders[index]);
            records[index] =
                map.get(this.distributionTargetKey(target.user, target.server, target.device)) ??
                    null;
        }
        return records;
    }
    async deleteDeviceSenderKey(target, groupId) {
        const sender = toSignalAddressParts(target);
        return this.withTransaction((db) => {
            const senderCount = this.countDelete(db, 'sender_keys', sender, groupId);
            const distributionCount = this.countDelete(db, 'sender_key_distribution', sender, groupId);
            return senderCount + distributionCount;
        });
    }
    async markForgetSenderKey(groupId, participants) {
        if (participants.length === 0) {
            return 0;
        }
        return this.withTransaction((db) => {
            let filters = '';
            const params = [this.options.sessionId, groupId];
            for (let index = 0; index < participants.length; index += 1) {
                if (index > 0) {
                    filters += ' OR ';
                }
                filters += '(sender_user = ? AND sender_server = ? AND sender_device = ?)';
                const sender = toSignalAddressParts(participants[index]);
                params.push(sender.user, sender.server, sender.device);
            }
            const where = `session_id = ? AND group_id = ? AND (${filters})`;
            db.run(`DELETE FROM sender_keys WHERE ${where}`, params);
            const senderCountRow = db.get('SELECT changes() AS total', []);
            const senderCount = senderCountRow
                ? asNumber(senderCountRow.total, 'sender_keys.changes')
                : 0;
            db.run(`DELETE FROM sender_key_distribution WHERE ${where}`, params);
            const distributionCountRow = db.get('SELECT changes() AS total', []);
            const distributionCount = distributionCountRow
                ? asNumber(distributionCountRow.total, 'sender_key_distribution.changes')
                : 0;
            return senderCount + distributionCount;
        });
    }
    async clear() {
        await this.withTransaction((db) => {
            db.run('DELETE FROM sender_keys WHERE session_id = ?', [this.options.sessionId]);
            db.run('DELETE FROM sender_key_distribution WHERE session_id = ?', [
                this.options.sessionId
            ]);
        });
    }
    countDelete(db, table, target, groupId) {
        const whereWithGroup = 'session_id = ? AND sender_user = ? AND sender_server = ? AND sender_device = ? AND group_id = ?';
        const whereAllGroups = 'session_id = ? AND sender_user = ? AND sender_server = ? AND sender_device = ?';
        db.run(`DELETE FROM ${table}
             WHERE ${groupId ? whereWithGroup : whereAllGroups}`, groupId
            ? [this.options.sessionId, target.user, target.server, target.device, groupId]
            : [this.options.sessionId, target.user, target.server, target.device]);
        const row = db.get('SELECT changes() AS total', []);
        return row ? asNumber(row.total, `${table}.changes`) : 0;
    }
    upsertSenderKeyDistributionRow(db, record, sender) {
        db.run(`INSERT INTO sender_key_distribution (
                session_id,
                group_id,
                sender_user,
                sender_server,
                sender_device,
                key_id,
                timestamp_ms
            ) VALUES (?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(session_id, group_id, sender_user, sender_server, sender_device) DO UPDATE SET
                key_id=excluded.key_id,
                timestamp_ms=excluded.timestamp_ms`, [
            this.options.sessionId,
            record.groupId,
            sender.user,
            sender.server,
            sender.device,
            record.keyId,
            record.timestampMs
        ]);
    }
    distributionRowKey(row) {
        return this.distributionTargetKey(asString(row.sender_user, 'sender_key_distribution.sender_user'), asString(row.sender_server, 'sender_key_distribution.sender_server'), asNumber(row.sender_device, 'sender_key_distribution.sender_device'));
    }
    distributionTargetKey(user, server, device) {
        return `${user}|${server}|${device}`;
    }
}
